void abort(void);
void exit(int);

double a[3] = {0.0, 1.0, 2.0};

void bar(int x, double *y) {
  if (x || *y != 1.0)
    abort();
}

int main() {
  double c;
  int    d;
  for (d = 0; d < 3; d++) {
    c = a[d];
    if (c > 0.0)
      goto e;
  }
  bar(1, &c);
  exit(1);
e:
  bar(0, &c);
  exit(0);
}


